px solid var(--line);display:flex;justify-content:space-between;align-items:center;gap:12px}.studio-head h3{margin:0;font-size:1.35rem}.studio-grid{display:grid;grid-template-columns:390px 1fr;min-height:700px}.chat{background:#faf8f3;border-right:1px solid var(--line);display:flex;flex-direction:column;min-width:0}.chat-top{padding:18px 20px;border-bottom:1px solid var(--line)}.chat-status{font-size:.72rem;color:var(--green);font-weight:800;text-transform:uppercase;letter-spacing:.12em}.messages{padding:18px;overflow:auto;height:570px;display:flex;flex-direction:column;gap:12px;scrollbar-width:none}.messages::-webkit-scrollbar{display:none}.msg{max-width:88%;padding:12px 14px;line-height:1.6;font-size:.87rem;border:1px solid var(--line);white-space:pre-wrap}.msg.ai{background:#fff}.msg.user{margin-left:auto;background:var(--green);border-color:var(--green);color:#fff}.msg.system{max-width:100%;background:#edf1eb;color:#43513f;border-color:#d9e1d5;font-size:.78rem}.chat-compose{border-top:1px solid var(--line);padding:12px;display:flex;gap:8px}.chat-compose textarea{resize:none;border:1px solid #d2cdc2;background:#fff;padding:11px 12px;min-height:50px;max-height:130px;flex:1;font:inherit;outline:none}.chat-compose textarea:focus{border-color:var(--green)}.send{border:0;background:var(--green);color:#fff;width:52px;font-size:18px}.workspace{min-width:0;background:#e9e5dc}.workspace-bar{padding:12px 16px;background:var(--paper);border-bottom:1px solid var(--line);display:flex;gap:8px;flex-wrap:wrap;align-items:center}.tool{border:1px solid #cfc9bd;background:#fff;padding:8px 11px;font-size:.75rem;font-weight:700;color:var(--ink)}.tool.active,.tool:hover{border-color:var(--green);color:var(--green)}.workspace-tabs{margin-left:auto;display:flex;gap:4px}.view{display:none}.view.active{display:block}.plan-wrap{padding:24px;overflow:auto;height:620px}.plan-board{position:relative;width:900px;height:560px;margin:auto;background:#fff;border:2px solid #2f362f;background-image:linear-gradient(#e9ede8 1px,transparent 1px),linear-gradient(90deg,#e9ede8 1px,transparent 1px);background-size:25px 25px;box-shadow:0 15px 35px rgba(30,35,29,.08)}.site-boundary{position:absolute;inset:18px;border:1px dashed #9ca697;pointer-events:none}.room{position:absolute;background:#fbfaf6;border:1px solid #4e584d;display:flex;align-items:center;justify-content:center;text-align:center;cursor:move;user-select:none;min-width:50px;min-height:35px;box-shadow:0 4px 12px rgba(0,0,0,.07)}.room.selected{border:2px solid var(--green);box-shadow:0 0 0 4px rgba(83,104,77,.12);z-index:20}.room .room-name{font-size:12px;font-weight:800}.room .room-size{font-size:10px;color:#737a72;margin-top:3px}.resize{position:absolute;right:-4px;bottom:-4px;width:11px;height:11px;background:var(--green);cursor:nwse-resize;border:2px solid #fff}.empty-state{height:560px;display:grid;place-items:center;text-align:center;color:var(--muted);padding:40px}.side-inspector{border-top:1px solid var(--line);background:var(--paper);padding:15px 20px;display:flex;gap:14px;align-items:end;flex-wrap:wrap}.field{display:flex;flex-direction:column;gap:5px}.field label{font-size:10px;text-transform:uppercase;letter-spacing:.1em;font-weight:800;color:var(--muted)}.field input{width:120px;padding:8px;border:1px solid #d3cec3}.field.name input{width:190px}.inspector-note{font-size:11px;color:var(--muted);margin-left:auto}.three{height:620px;background:#dfe5df;position:relative;overflow:hidden}.three canvas{display:block;width:100%;height:100%}.three-hint{position:absolute;left:16px;top:16px;background:rgba(255,253,249,.94);padding:11px 13px;font-size:11px;box-shadow:0 8px 25px rgba(0,0,0,.12);max-width:300px}.three-tools{position:absolute;right:16px;top:16px;display:flex;gap:5px}.three-tools button{background:rgba(28,35,29,.86);color:#fff;border:1px solid rgba(255,255,255,.2);padding:8px 10px;font-size:11px}.result-summary{padding:22px 26px;background:#263127;color:#fff;display:flex;gap:30px;flex-wrap:wrap}.result-summary strong{font-size:1.1rem;display:block}.result-summary span{font-size:.75rem;color:#c9d1c6}.help-strip{padding:28px 0}.help-card{height:100%;padding:25px;border-top:2px solid var(--green);background:#fffdf9}.loading{position:fixed;inset:0;background:rgba(18,23,19,.75);z-index:5000;display:none;align-items:center;justify-content:center}.loading-box{background:var(--paper);padding:35px;width:min(440px,92vw);text-align:center}.bar{height:3px;background:#ddd;margin-top:18px;overflow:hidden}.bar i{display:block;width:35%;height:100%;background:var(--green);animation:load 1.1s infinite}@keyframes load{to{transform:translateX(350%)}}footer{background:#171d18;color:#dfe5dc;padding:45px 0}.floating-map{position:fixed;right:20px;bottom:20px;z-index:1000;border-radius:30px;background:var(--green);color:#fff;padding:12px 16px;font-weight:800;box-shadow:0 12px 30px rgba(0,0,0,.22)}@media(max-width:1100px){.studio-grid{grid-template-columns:330px 1fr}}@media(max-width:900px){.studio-grid{grid-template-columns:1fr}.chat{border-right:0;border-bottom:1px solid var(--line)}.messages{height:390px}.plan-wrap{height:570px}.three{height:520px}}@media(max-width:650px){.hero{min-height:620px}.hero-content{padding:90px 0}.section{padding:65px 0}.studio-head{padding:17px}.plan-board{transform-origin:top left}.plan-wrap{padding:12px}.inspector-note{width:100%;margin-left:0}.floating-map{right:12px;bottom:12px}}
