<script type="importmap">{"imports":{"three":"https://cdn.jsdelivr.net/npm/three@0.180.0/build/three.module.js","three/addons/":"https://cdn.jsdelivr.net/npm/three@0.180.0/examples/jsm/"}}</script>
<script type="module">
import * as THREE from 'three';
import {OrbitControls} from 'three/addons/controls/OrbitControls.js';
const $=s=>document.querySelector(s); const messages=$('#messages'); let conversation=''; let plan=null; let selected=-1; let dragging=null; let resizing=null;
const addMsg=(text,who='ai')=>{const d=document.createElement('div');d.className='msg '+who;d.textContent=text;messages.appendChild(d);messages.scrollTop=messages.scrollHeight};
const allText=()=>[...messages.querySelectorAll('.msg')].map(x=>x.textContent).join('\n');
function extractPlot(text){const m=text.match(/(\d+(?:\.\d+)?)\s*(?:x|×|by)\s*(\d+(?:\.\d+)?)\s*(?:m|metres|meters)?/i);return m?{w:parseFloat(m[1]),d:parseFloat(m[2])}:null}
function explicitBedrooms(text){let m=text.match(/(?:five|four|three|two|one|six|seven|eight|nine|ten|5|4|3|2|1|6|7|8|9|10)\s*(?:bedroom|bedrooms|rooms?\s*(?:ya|za)?\s*bed)/i);if(!m)return null;const words={one:1,two:2,three:3,four:4,five:5,six:6,seven:7,eight:8,nine:9,ten:10};return words[m[1].toLowerCase()]||parseInt(m[1]);}
function conversationReady(){const t=allText();const p=extractPlot(t);const beds=explicitBedrooms(t);return {plot:p,beds:beds,style:/luxury|contemporary|modern|minimalist|tropical|courtyard/i.test(t)};}
async function sendChat(){const input=$('#chatInput');const text=input.value.trim();if(!text)return;input.value='';addMsg(text,'user');conversation+=text+'\n';const state=conversationReady();if(!state.plot){addMsg('Nimeelewa mahitaji yako. Kabla sijatengeneza ramani, nahitaji dimensions za plot — mfano 20 × 30 metres.');return;}if(!state.beds){addMsg('Nimepata plot dimensions. Sasa niambie idadi kamili ya bedrooms/rooms unazotaka, na kama kuna nafasi maalum kama courtyard.');return;}addMsg('Nimehifadhi mahitaji hayo. Ukiwa tayari, bonyeza Generate — AI itatengeneza plan yenye idadi hiyo bila kuongeza rooms kwa kubahatisha.','ai');}
$('#sendBtn').onclick=sendChat;$('#chatInput').addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();sendChat()}});
function setLoading(v){$('#loading').style.display=v?'flex':'none'}
function clearBoard(){document.querySelectorAll('.room').forEach(x=>x.remove())}
function renderPlan(data){plan={...data,rooms:(data.rooms||[]).map((r,i)=>({...r,x:r.x??(20+(i%4)*210),y:r.y??(35+Math.floor(i/4)*180),width:+r.width||6,depth:+r.depth||5}))};clearBoard();$('#emptyPlan').style.display='none';selected=-1;plan.rooms.forEach((r,i)=>makeRoom(r,i));$('#planState').textContent=`${plan.rooms.length} spaces · editable`;$('#summary').style.display='flex';$('#summary').innerHTML=`<div><strong>${escapeHtml(plan.title||'AI architectural concept')}</strong><span>${escapeHtml(plan.summary||'Editable concept generated from your conversation.')}</span></div><div><strong>${plan.house_width||'—'} × ${plan.house_depth||'—'} m</strong><span>Building footprint</span></div><div><strong>${plan.rooms.filter(r=>String(r.type||'').toLowerCase()==='bedroom').length}</strong><span>Bedrooms</span></div>`;init3D();}
function escapeHtml(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]))}
function makeRoom(r,i){const el=document.createElement('div');el.className='room';el.dataset.i=i;el.style.left=r.x+'px';el.style.top=r.y+'px';el.style.width=Math.max(60,r.width*35)+'px';el.style.height=Math.max(45,r.depth*35)+'px';el.innerHTML=`<div><div class="room-name">${escapeHtml(r.name)}</div><div class="room-size">${(+r.width).toFixed(1)} × ${(+r.depth).toFixed(1)} m</div></div><span class="resize"></span>`;$('#planBoard').appendChild(el);el.addEventListener('pointerdown',e=>{if(e.target.classList.contains('resize')){resizing={i,ox:e.clientX,oy:e.clientY,w:+r.width,d:+r.depth};}else{selected=i;selectRoom();dragging={i,ox:e.clientX,oy:e.clientY,x:r.x,y:r.y};}el.setPointerCapture(e.pointerId);e.preventDefault()});el.addEventListener('pointermove',e=>{if(dragging&&dragging.i===i){const dx=(e.clientX-dragging.ox),dy=(e.clientY-dragging.oy);r.x=Math.max(20,Math.min(850,dragging.x+dx));r.y=Math.max(20,Math.min(500,dragging.y+dy));el.style.left=r.x+'px';el.style.top=r.y+'px';}if(resizing&&resizing.i===i){r.width=Math.max(2,(resizing.w+(e.clientX-resizing.ox)/35));r.depth=Math.max(2,(resizing.d+(e.clientY-resizing.oy)/35));el.style.width=Math.max(60,r.width*35)+'px';el.style.height=Math.max(45,r.depth*35)+'px';el.querySelector('.room-size').textContent=`${r.width.toFixed(1)} × ${r.depth.toFixed(1)} m`;}});el.addEventListener('pointerup',()=>{if(dragging||resizing)init3D();dragging=null;resizing=null});}
function selectRoom(){document.querySelectorAll('.room').forEach((e,i)=>e.classList.toggle('selected',i===selected));const ins=$('#inspector');if(selected<0){ins.style.display='none';return}ins.style.display='flex';const r=plan.rooms[selected];$('#roomName').value=r.name||'';$('#roomW').value=r.width||'';$('#roomD').value=r.depth||'';}
$('#planBoard').addEventListener('click',e=>{const el=e.target.closest('.room');if(el){selected=+el.dataset.i;selectRoom()}});
$('#applyEdit').onclick=()=>{if(selected<0)return;const r=plan.rooms[selected];r.name=$('#roomName').value.trim()||r.name;r.width=Math.max(2,+$('#roomW').value||r.width);r.depth=Math.max(2,+$('#roomD').value||r.depth);renderPlan(plan);selected=Math.min(selected,plan.rooms.length-1);selectRoom();};
$('#deleteRoom').onclick=()=>{if(selected<0)return;plan.rooms.splice(selected,1);renderPlan(plan)};
$('#resetBtn').onclick=()=>{if(window._aiPlan)renderPlan(window._aiPlan)};
async function generate(){const state=conversationReady();if(!state.plot||!state.beds){addMsg('Nahitaji kwanza plot dimensions na idadi kamili ya bedrooms/rooms kabla ya generate.','ai');return;}setLoading(true);try{const fd=new FormData();fd.append('project','AI Architecture Studio');fd.append('client','');fd.append('contact','');fd.append('location','');fd.append('plot_width',state.plot.w);fd.append('plot_depth',state.plot.d);fd.append('road_side','North');fd.append('style','');fd.append('brief',allText());const res=await fetch('api/generate.php',{method:'POST',body:fd});const j=await res.json();if(!j.ok){addMsg(j.message||'AI haikuweza kutengeneza plan.','ai');return;}const data=j.data||j.plan||j;window._aiPlan=JSON.parse(JSON.stringify(data));renderPlan(data);addMsg('Plan imetengenezwa. Sasa unaweza kubadilisha position, width, depth au jina la room. Ukimaliza, fungua 3D — itaonyesha geometry uliyo-edit.','ai');}catch(e){addMsg('Kuna tatizo la mawasiliano na AI. Jaribu tena.','ai');}finally{setLoading(false)}}
$('#generateBtn').onclick=generate;
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-view]').forEach(x=>x.classList.remove('active'));b.classList.add('active');document.querySelectorAll('.view').forEach(v=>v.classList.remove('active'));$('#'+(b.dataset.view==='plan'?'planView':'threeView')).classList.add('active');if(b.dataset.view==='three')setTimeout(()=>{if(window._threeResize)window._threeResize()},50)});
let scene,camera,renderer,controls,modelGroup;
function init3D(){if(!scene){scene=new THREE.Scene();scene.background=new THREE.Color(0xe5e9e4);camera=new THREE.PerspectiveCamera(45,1,.1,500);camera.position.set(18,18,22);renderer=new THREE.WebGLRenderer({antialias:true,powerPreference:'high-performance'});renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;$('#threeRoot').appendChild(renderer.domElement);controls=new OrbitControls(camera,renderer.domElement);controls.enableDamping=true;controls.target.set(0,0,0);const hemi=new THREE.HemisphereLight(0xffffff,0x5b655b,2.5);scene.add(hemi);const sun=new THREE.DirectionalLight(0xffffff,3.2);sun.position.set(12,24,10);sun.castShadow=true;scene.add(sun);const fill=new THREE.DirectionalLight(0xfff4df,1.4);fill.position.set(-12,10,-8);scene.add(fill);const ground=new THREE.Mesh(new THREE.PlaneGeometry(100,100),new THREE.MeshStandardMaterial({color:0xd4d8d1,roughness:1}));ground.rotation.x=-Math.PI/2;ground.position.y=-.08;ground.receiveShadow=true;scene.add(ground);window._threeResize=resize3D;window.addEventListener('resize',resize3D);(function loop(){requestAnimationFrame(loop);controls.update();renderer.render(scene,camera)})()}build3D()}
function resize3D(){const box=$('#threeRoot').getBoundingClientRect();const w=Math.max(300,box.width),h=Math.max(350,box.height);camera.aspect=w/h;camera.updateProjectionMatrix();renderer.setSize(w,h,false)}
function build3D(){if(!scene||!plan)return;if(modelGroup)scene.remove(modelGroup);modelGroup=new THREE.Group();const matWall=new THREE.MeshStandardMaterial({color:0xf4f0e7,roughness:.72,metalness:.02});const matDark=new THREE.MeshStandardMaterial({color:0x394239,roughness:.6});const matGlass=new THREE.MeshStandardMaterial({color:0x9db8c0,roughness:.18,metalness:.05,transparent:true,opacity:.72});const matRoof=new THREE.MeshStandardMaterial({color:0x303730,roughness:.78});const maxX=Math.max(...plan.rooms.map(r=>r.x+(+r.width||5)*35)),maxY=Math.max(...plan.rooms.map(r=>r.y+(+r.depth||5)*35));const scale=.16;const offsetX=-maxX*scale/2,offsetZ=-maxY*scale/2;plan.rooms.forEach((r,i)=>{const w=Math.max(2,+r.width||5)*scale,d=Math.max(2,+r.depth||5)*scale;const x=(r.x*scale)+offsetX+w/2,z=(r.y*scale)+offsetZ+d/2;const type=String(r.type||'').toLowerCase();const h=type==='courtyard'?0.18:3.0;const box=new THREE.Mesh(new THREE.BoxGeometry(w,h,d),type==='courtyard'?new THREE.MeshStandardMaterial({color:0x91a782,roughness:1}):matWall);box.position.set(x,h/2,z);box.castShadow=true;box.receiveShadow=true;modelGroup.add(box);if(type!=='courtyard'){const roof=new THREE.Mesh(new THREE.BoxGeometry(w+.06,.16,d+.06),matRoof);roof.position.set(x,h+.08,z);roof.castShadow=true;modelGroup.add(roof);const front=new THREE.Mesh(new THREE.BoxGeometry(Math.min(w*.42,2.2),1.25,.06),matGlass);front.position.set(x,h*.45,z+d/2+.035);modelGroup.add(front);}});const slab=new THREE.Mesh(new THREE.BoxGeometry(maxX*scale+.8,.18,maxY*scale+.8),matDark);slab.position.set(0,-.09,0);slab.receiveShadow=true;modelGroup.add(slab);scene.add(modelGroup);resize3D();camera.position.set(Math.max(13,maxX*scale*.9),Math.max(11,maxY*scale*.9),Math.max(15,maxY*scale*1.05));controls.target.set(0,1,0);controls.update()}
$('#threeIso').onclick=()=>{camera.position.set(18,16,20);controls.target.set(0,1,0);controls.update()};$('#threeTop').onclick=()=>{camera.position.set(0,30,.01);controls.target.set(0,0,0);controls.update()};$('#threeFront').onclick=()=>{camera.position.set(0,7,28);controls.target.set(0,1,0);controls.update()};
</script>
</body></html>